            aS[(arow + 32) * RowWords + a4 * 2] = PackF16Sm75(pa1.X * s, pa1.Y * s);
            aS[(arow + 32) * RowWords + a4 * 2 + 1] = PackF16Sm75(pa1.Z * s, pa1.W * s);
            aS[(arow + 64) * RowWords + a4 * 2] = PackF16Sm75(pa2.X * s, pa2.Y * s);
